entries[370456] = { ["name"] = "Phial of Icy Preservation", ["text"] = "2.5 sec cast\nReagents:\nAwakened Decay , Awakened Frost , Saxifrage (9), Draconic Vial (2)\nOptional Reagents:\nAlchemical Catalyst (#94) , Lesser Illustrious Insight (#92)\nThis putrid recipe requires an altar infused with powerful decay magic, rumored to be deep in Brackenhide Hollow.\nDiscovery:\nPhial Experimentation\nRequires:\nSpecialization: Alchemical Theory - Decayology\n\nToxic\n\nUse: Damage taken is decreased by 4% while over 50% health, but increased by 4% while under 50% health.\n\nLasts 30 min and through death. Consuming an identical phial will add another 30 min.\n61" }
entries[370457] = { ["name"] = "Iced Phial of Corrupting Rage", ["text"] = "2.5 sec cast\nReagents:\nAwakened Decay , Awakened Frost , Writhebark (9), Draconic Vial (2)\nOptional Reagents:\nAlchemical Catalyst (#94) , Lesser Illustrious Insight (#92)\nThis putrid recipe requires an altar infused with powerful decay magic, rumored to be deep in Brackenhide Hollow.\nDiscovery:\nPhial Experimentation\nRequires:\nSpecialization: Alchemical Theory - Decayology\n\nToxic\n\nUse: Gain Corrupting Rage which grants 38 Critical Strike rating. After suffering 400% of your health in damage, you are afflicted with Overwhelming Rage instead which causes you to take 25% of your health as Nature damage over 15 sec, after which the cycle begins anew.\n\nLasts 30 min and through death. Consuming an identical phial will add another 30 min.\n61" }
