entries[370533] = { ["name"] = "Residual Neural Channeling Agent", ["text"] = "2 sec cast\nReagents:\nAwakened Air , Awakened Earth , Saxifrage (10), Draconic Vial (5)\nOptional Reagents:\nAlchemical Catalyst (#91) , Lesser Illustrious Insight (#92)\nDiscovery:\nPotion Experimentation\n\nUse: While dead, assault your enemy's consciousness with what remains of your own, dealing [source value] Nature damage over 18 sec to your target. Should you be revived, the remaining damage will be dealt instantly. Releasing your spirit will return your consciousness to you and cancel the effect.\n\nShares a cooldown with combat potions.\n61", ["unresolvedValues"] = true }
