entries[370668] = { ["name"] = "Potion Cauldron of Power", ["text"] = "2 sec cast 2\nReagents:\nElemental Potion of Power (100), Omnium Draconis (10)\nOptional Reagents:\nAlchemical Catalyst (#91) , Illustrious Insight (#93)\nSpecialization:\nPotion Mastery - Batch Production (10)\n\nBinds to Warband\n\nUse: Creates a cauldron that raid members can use to acquire Fleeting Elemental Potions of Power. When consumed, their primary stat is increased by 18 for 30 sec.\n\nCauldron has 120 uses and each provides 5 potions. The cauldron lasts for 20 min.\n61" }
