entries[370672] = { ["name"] = "Potion Cauldron of Ultimate Power", ["text"] = "2 sec cast 2\nReagents:\nElemental Potion of Power (150), Omnium Draconis (20)\nOptional Reagents:\nAlchemical Catalyst (#91) , Illustrious Insight (#93)\nDrop:\nAssault of the Zaqali\nZone:\nAberrus, the Shadowed Crucible\nLearned From:\nElemental Codex of Ultimate Power\nRecipe:\nPurchasable on the Auction House\n\nBinds to Warband\n\nUse: Creates a cauldron that raid members can use to acquire Fleeting Elemental Potions of Ultimate Power. When consumed, their primary stat is increased by 24 for 30 sec.\n\nCauldron has 120 uses and each provides 5 potions. The cauldron lasts for 20 min.\n61" }
entries[370673] = { ["name"] = "Cauldron of the Pooka", ["text"] = "2 sec cast\nReagents:\nTuft of Primal Wool , Primal Convergent (2), Omnium Draconis\nOptional Reagents:\nAlchemical Catalyst (#91) , Lesser Illustrious Insight (#92)\nFishing:\nDraconic Recipe in a Bottle\nRecipe:\nPurchasable on the Auction House\n\nBinds to Warband\n\nUse: Set out a Cauldron of the Pooka for 3 min. Allies can take a sample of the suspiciously fuzzy liquid as a refreshing drink to restore 60% mana over 30 sec.\n\nEach sip has a chance to transform them into a cute and cuddly creature!\n61" }
entries[370676] = { ["name"] = "Sustaining Alchemist Stone", ["text"] = "2 sec cast 3\nReagents:\nGlowing Titan Orb , Phial of Tepid Versatility (6), Phial of Elemental Chaos (6), Primal Convergent (4), Spark (#247)\nOptional Reagents:\nAlchemical Catalyst (#94) , Illustrious Insight (#93) , Infuse with Power (#126)\nVendor:\nDothenos\nZone:\nValdrakken\nCost:\n400\n\nVendor:\nUnatos\nZone:\nValdrakken\nCost:\n400\n\nSustaining Alchemist Stone\nBinds when picked up\nUnique-Equipped: Alchemist Stone (1)Trinket\n+ 342 Versatility\nEquip: Your spells and abilities have a chance to increase your primary stat by 687 for 10 sec and extend the duration of your active phial by 60 sec.\n60\n\"Can be used for transmutations in place of a Philosopher's Stone.\"" }
